// @ts-check
// Third-party licenses (« Licences tierces ») dialog, opened from the Info
// (« Informations ») dialog: shows `ui/third-party-notices.txt`, the license
// notices for everything the application embeds without having written it —
// Rust crates, JS vendors and their dependencies, jars. File generated by
// `scripts/third_party_notices.py`, embedded with the other assets (compressed
// by Tauri) and read by `fetch` on first open: ~1.3 MB of plain text that no
// other view loads.

import { t } from "./i18n.js";

// Static elements of ui/index.html.
const dialog = /** @type {HTMLDialogElement} */ (document.getElementById("notices-dialog"));
const body = /** @type {HTMLPreElement} */ (document.getElementById("notices-body"));

// Once the text is loaded: frozen at build time, no need to re-read it. A
// failure is not remembered — reopening retries, with the message in the
// current language.
let loaded = false;

export async function openNotices() {
  if (!loaded) {
    try {
      const resp = await fetch("third-party-notices.txt");
      if (!resp.ok) throw new Error(`HTTP ${resp.status}`);
      body.textContent = await resp.text();
      body.classList.remove("settings-error");
      loaded = true;
    } catch (err) {
      body.textContent = t("notices.load_failed", { error: String(err) });
      body.classList.add("settings-error");
    }
  }
  dialog.showModal();
  body.scrollTop = 0;
}

export function initNotices() {
  /** @type {HTMLButtonElement} */ (document.getElementById("notices-close")).addEventListener(
    "click",
    () => dialog.close(),
  );
}
